#!/usr/bin/env python3
"""Validate Halcyon Threshold ledger entries.

Enforces the rules in ledger/SCHEMA.md. Standard library only, no dependencies.

Usage:
    python tools/validate.py                 # validate everything
    python tools/validate.py --strict        # treat placeholder entries as errors
    python tools/validate.py --publishable   # also apply the pre-publication gates

Exit code 0 if clean, 1 if any error was found.
"""

from __future__ import annotations

import argparse
import datetime as dt
import json
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
ENTRY_DIR = ROOT / "ledger" / "entries"

ID_RE = re.compile(r"^HT-\d{4}-\d{3}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")

STATUSES = {
    "met",
    "partially-met",
    "not-met",
    "unclear",
    "not-yet-due",
    "superseded",
    "withdrawn",
}
CONFIDENCES = {"low", "medium", "high"}

# Statuses that assert a shortfall and therefore require right of reply before publishing.
ADVERSE_STATUSES = {"not-met", "partially-met"}

REVIEW_MAX_AGE_DAYS = 180
MIN_WOULD_CHANGE_CHARS = 20

TOP_LEVEL_REQUIRED = [
    "id",
    "developer",
    "topic",
    "title",
    "commitment",
    "observations",
    "assessment",
    "right_of_reply",
    "corrections",
    "conflicts_of_interest",
    "last_reviewed",
    "reviewer",
]

SOURCE_REQUIRED = [
    "quote",
    "source_title",
    "source_url",
    "archive_url",
    "source_published",
    "retrieved",
]

ASSESSMENT_REQUIRED = ["status", "confidence", "reasoning", "what_would_change_this"]


class Problems:
    """Collects errors and warnings, tagged by file."""

    def __init__(self) -> None:
        self.errors: list[str] = []
        self.warnings: list[str] = []

    def error(self, where: str, msg: str) -> None:
        self.errors.append(f"{where}: {msg}")

    def warn(self, where: str, msg: str) -> None:
        self.warnings.append(f"{where}: {msg}")


def is_nonempty_str(value) -> bool:
    return isinstance(value, str) and value.strip() != ""


def parse_date(value):
    """Return a date, or None if unparseable."""
    if not isinstance(value, str) or not DATE_RE.match(value):
        return None
    try:
        return dt.date.fromisoformat(value)
    except ValueError:
        return None


def check_date(p: Problems, where: str, field: str, value, allow_unknown: bool = False) -> None:
    if allow_unknown and value == "unknown":
        p.warn(where, f"{field} is 'unknown' — note in the entry that the source is undated")
        return
    parsed = parse_date(value)
    if parsed is None:
        p.error(where, f"{field} must be YYYY-MM-DD" + (" or 'unknown'" if allow_unknown else "")
                + f" (got {value!r})")
        return
    if parsed > dt.date.today():
        p.error(where, f"{field} is in the future ({value})")


def check_url(p: Problems, where: str, field: str, value) -> None:
    if not is_nonempty_str(value):
        p.error(where, f"{field} is required")
        return
    if not value.startswith(("http://", "https://")):
        p.error(where, f"{field} must be an absolute http(s) URL (got {value!r})")


def check_source(p: Problems, where: str, label: str, source) -> None:
    if not isinstance(source, dict):
        p.error(where, f"{label} must be an object")
        return
    for field in SOURCE_REQUIRED:
        if field not in source:
            p.error(where, f"{label}.{field} is missing")
    for field in ("quote", "source_title"):
        if field in source and not is_nonempty_str(source.get(field)):
            p.error(where, f"{label}.{field} must be a non-empty string")
    if "source_url" in source:
        check_url(p, where, f"{label}.source_url", source.get("source_url"))
    if "archive_url" in source:
        check_url(p, where, f"{label}.archive_url", source.get("archive_url"))
        # Methodology section 3.3: the snapshot is the point. A snapshot that is just the
        # live URL again is not a snapshot.
        if source.get("archive_url") == source.get("source_url"):
            p.error(where, f"{label}.archive_url is identical to source_url — no snapshot taken")
    if "source_published" in source:
        check_date(p, where, f"{label}.source_published", source.get("source_published"),
                   allow_unknown=True)
    if "retrieved" in source:
        check_date(p, where, f"{label}.retrieved", source.get("retrieved"))


def check_assessment(p: Problems, where: str, assessment) -> str | None:
    if not isinstance(assessment, dict):
        p.error(where, "assessment must be an object")
        return None
    for field in ASSESSMENT_REQUIRED:
        if not is_nonempty_str(assessment.get(field)):
            p.error(where, f"assessment.{field} is required and must be non-empty")

    status = assessment.get("status")
    if status is not None and status not in STATUSES:
        p.error(where, f"assessment.status {status!r} not in {sorted(STATUSES)}")

    confidence = assessment.get("confidence")
    if confidence is not None and confidence not in CONFIDENCES:
        p.error(where, f"assessment.confidence {confidence!r} not in {sorted(CONFIDENCES)}")

    wct = assessment.get("what_would_change_this")
    if is_nonempty_str(wct) and len(wct.strip()) < MIN_WOULD_CHANGE_CHARS:
        p.error(where, "assessment.what_would_change_this is too short to be meaningful "
                       f"(min {MIN_WOULD_CHANGE_CHARS} chars)")

    # Methodology section 2: no motive claims. Heuristic nudge, not a hard rule.
    reasoning = assessment.get("reasoning") or ""
    for phrase in ("deliberately", "intended to", "tried to hide", "wanted to",
                   "in order to avoid", "knowingly"):
        if phrase in reasoning.lower():
            p.warn(where, f"assessment.reasoning contains {phrase!r} — reads as a motive "
                          "claim; restate as conduct")
    return status


def check_right_of_reply(p: Problems, where: str, ror, status: str | None,
                         publishable: bool) -> None:
    if not isinstance(ror, dict):
        p.error(where, "right_of_reply must be an object")
        return
    if not isinstance(ror.get("requested"), bool):
        p.error(where, "right_of_reply.requested must be true or false")
    if ror.get("requested"):
        check_date(p, where, "right_of_reply.requested_on", ror.get("requested_on"))
    if ror.get("response_received_on") is not None:
        check_date(p, where, "right_of_reply.response_received_on",
                   ror.get("response_received_on"))
        if not is_nonempty_str(ror.get("response_text")):
            p.error(where, "a response date is recorded but response_text is empty — "
                           "the methodology requires publishing the response verbatim")
    if publishable and status in ADVERSE_STATUSES and not ror.get("requested"):
        p.error(where, f"status {status!r} cannot be published until right of reply has been "
                       "requested (METHODOLOGY section 6)")


def check_corrections(p: Problems, where: str, corrections) -> None:
    if not isinstance(corrections, list):
        p.error(where, "corrections must be an array")
        return
    for i, correction in enumerate(corrections):
        label = f"corrections[{i}]"
        if not isinstance(correction, dict):
            p.error(where, f"{label} must be an object")
            continue
        for field in ("date", "was", "now", "raised_by"):
            if not is_nonempty_str(correction.get(field)):
                p.error(where, f"{label}.{field} is required")
        if "date" in correction:
            check_date(p, where, f"{label}.date", correction.get("date"))


def validate_entry(path: pathlib.Path, p: Problems, seen_ids: dict[str, str],
                   strict: bool, publishable: bool) -> None:
    where = path.name
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        p.error(where, f"invalid JSON: {exc}")
        return
    if not isinstance(data, dict):
        p.error(where, "top level must be an object")
        return

    is_placeholder = data.get("placeholder") is True
    if is_placeholder:
        if strict or publishable:
            p.error(where, "placeholder entry present (excluded from publication)")
        else:
            p.warn(where, "placeholder entry — example data, not a real finding")

    for field in TOP_LEVEL_REQUIRED:
        if field not in data:
            p.error(where, f"{field} is missing")

    entry_id = data.get("id")
    if not is_nonempty_str(entry_id) or not ID_RE.match(entry_id or ""):
        p.error(where, f"id must match HT-YYYY-NNN (got {entry_id!r})")
    else:
        if entry_id in seen_ids:
            p.error(where, f"duplicate id {entry_id} (also in {seen_ids[entry_id]})")
        else:
            seen_ids[entry_id] = where
        if path.stem != entry_id:
            p.error(where, f"filename does not match id {entry_id}")

    for field in ("developer", "topic", "title", "reviewer", "conflicts_of_interest"):
        if field in data and not is_nonempty_str(data.get(field)):
            p.error(where, f"{field} must be a non-empty string")

    if "commitment" in data:
        check_source(p, where, "commitment", data.get("commitment"))

    observations = data.get("observations")
    if not isinstance(observations, list):
        if "observations" in data:
            p.error(where, "observations must be an array (may be empty)")
    else:
        for i, observation in enumerate(observations):
            check_source(p, where, f"observations[{i}]", observation)

    status = check_assessment(p, where, data.get("assessment")) if "assessment" in data else None

    # An empty observation list is legitimate only for statuses that assert nothing.
    if isinstance(observations, list) and not observations:
        if status in ADVERSE_STATUSES or status == "met":
            p.error(where, f"status {status!r} asserts a finding but there are no observations")
        else:
            p.warn(where, "no observations recorded — acceptable for an open question, and "
                          "'unclear' is itself a finding worth publishing")

    if "right_of_reply" in data:
        check_right_of_reply(p, where, data.get("right_of_reply"), status, publishable)
    if "corrections" in data:
        check_corrections(p, where, data.get("corrections"))

    reviewed = data.get("last_reviewed")
    check_date(p, where, "last_reviewed", reviewed)
    reviewed_date = parse_date(reviewed)
    if reviewed_date is not None:
        age = (dt.date.today() - reviewed_date).days
        if age > REVIEW_MAX_AGE_DAYS:
            p.error(where, f"last_reviewed is {age} days old (limit {REVIEW_MAX_AGE_DAYS}) — "
                           "stale entries get cited; review or retire it")
        elif age > REVIEW_MAX_AGE_DAYS - 30:
            p.warn(where, f"last_reviewed is {age} days old — review due soon")


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate ledger entries.")
    parser.add_argument("--strict", action="store_true",
                       help="treat placeholder entries as errors")
    parser.add_argument("--publishable", action="store_true",
                       help="apply pre-publication gates (right of reply, no placeholders)")
    args = parser.parse_args()

    if not ENTRY_DIR.is_dir():
        print(f"error: no entry directory at {ENTRY_DIR}", file=sys.stderr)
        return 1

    paths = sorted(ENTRY_DIR.glob("*.json"))
    if not paths:
        print(f"error: no entries found in {ENTRY_DIR}", file=sys.stderr)
        return 1

    p = Problems()
    seen_ids: dict[str, str] = {}
    for path in paths:
        validate_entry(path, p, seen_ids, args.strict, args.publishable)

    for warning in p.warnings:
        print(f"WARN  {warning}")
    for error in p.errors:
        print(f"ERROR {error}")

    print(f"\n{len(paths)} entr{'y' if len(paths) == 1 else 'ies'} checked; "
          f"{len(p.errors)} error(s), {len(p.warnings)} warning(s).")
    return 1 if p.errors else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Build the Halcyon Threshold static site from ledger entries.

Standard library only. Writes to site/ by default. Placeholder entries are never rendered.

Usage:
    python tools/render.py
    python tools/render.py --out site --include-drafts

Run tools/validate.py --publishable first. This script refuses to render an entry that
fails the publication gates it can check locally.
"""

from __future__ import annotations

import argparse
import datetime as dt
import html
import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
ENTRY_DIR = ROOT / "ledger" / "entries"

ADVERSE_STATUSES = {"not-met", "partially-met"}

STATUS_LABEL = {
    "met": "Met",
    "partially-met": "Partially met",
    "not-met": "Not met",
    "unclear": "Unclear from public evidence",
    "not-yet-due": "Not yet due",
    "superseded": "Superseded",
    "withdrawn": "Withdrawn",
}

STYLE = """
:root { --fg:#1a1a1a; --muted:#5c5c5c; --rule:#dcdcdc; --bg:#fdfdfc; }
* { box-sizing:border-box; }
body { margin:0 auto; padding:2.5rem 1.25rem 5rem; max-width:46rem; background:var(--bg);
  color:var(--fg); font:16px/1.65 Georgia, "Iowan Old Style", serif; }
header.site { border-bottom:2px solid var(--fg); padding-bottom:.75rem; margin-bottom:2rem; }
header.site h1 { font-size:1.5rem; margin:0; letter-spacing:.01em; }
header.site p { margin:.4rem 0 0; color:var(--muted); font-size:.95rem; }
a { color:#1a4d7a; }
h2 { font-size:1.2rem; margin-top:2.5rem; }
h3 { font-size:1rem; text-transform:uppercase; letter-spacing:.07em; color:var(--muted);
  margin:2rem 0 .5rem; font-family:system-ui, sans-serif; }
blockquote { margin:.5rem 0 .5rem 0; padding:.6rem 0 .6rem 1rem;
  border-left:3px solid var(--rule); color:#333; }
.cite { font:13px/1.5 system-ui, sans-serif; color:var(--muted); }
.assessment { border:1px solid var(--rule); background:#fff; padding:1rem 1.1rem;
  margin:1.25rem 0; }
.assessment h3 { margin-top:0; }
.status { font-family:system-ui, sans-serif; font-size:.8rem; font-weight:600;
  text-transform:uppercase; letter-spacing:.06em; border:1px solid var(--fg);
  padding:.15rem .5rem; display:inline-block; }
.meta { font:13px/1.6 system-ui, sans-serif; color:var(--muted); }
ul.entries { list-style:none; padding:0; }
ul.entries li { border-bottom:1px solid var(--rule); padding:.9rem 0; }
ul.entries .dev { font:12px/1.4 system-ui, sans-serif; text-transform:uppercase;
  letter-spacing:.07em; color:var(--muted); }
footer { margin-top:4rem; border-top:1px solid var(--rule); padding-top:1rem;
  font:13px/1.6 system-ui, sans-serif; color:var(--muted); }
.notice { background:#fff8e5; border:1px solid #e4cf8a; padding:.8rem 1rem; font-size:.9rem; }
"""

DISCLOSURE = (
    "Halcyon Threshold is an independent project. It records public commitments and publicly "
    "verifiable conduct; it does not allege motive and does not publish private information. "
    "Assessments are the project's own judgement and are kept separate from the cited "
    "evidence so that readers can check the sources and disagree. Corrections are welcome and "
    "are logged in public."
)


def e(text) -> str:
    return html.escape("" if text is None else str(text), quote=True)


def page(title: str, body: str, built: str) -> str:
    return f"""<!doctype html>
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{e(title)}</title>
<style>{STYLE}</style>
<header class="site">
  <h1><a href="index.html" style="color:inherit;text-decoration:none">Halcyon Threshold</a></h1>
  <p>A citation-first record of frontier AI safety commitments and what followed.</p>
</header>
{body}
<footer>
  <p>{e(DISCLOSURE)}</p>
  <p>Built {e(built)}. Methodology and corrections policy are published in full.</p>
</footer>
</html>
"""


def render_source(source: dict, heading: str) -> str:
    published = source.get("source_published") or "unknown"
    note = source.get("note")
    parts = [
        f"<h3>{e(heading)}</h3>",
        f"<blockquote>{e(source.get('quote'))}</blockquote>",
        '<p class="cite">',
        f"{e(source.get('source_title'))} — published {e(published)}; ",
        f"retrieved {e(source.get('retrieved'))}. ",
        f'<a href="{e(source.get("source_url"))}">source</a> · ',
        f'<a href="{e(source.get("archive_url"))}">archived copy</a>',
    ]
    if note:
        parts.append(f"<br>{e(note)}")
    parts.append("</p>")
    return "\n".join(parts)


def render_entry(entry: dict, built: str) -> str:
    assessment = entry.get("assessment", {})
    status = assessment.get("status", "unclear")
    body = [
        f"<h2>{e(entry.get('title'))}</h2>",
        f'<p class="meta">{e(entry.get("developer"))} · {e(entry.get("topic"))} · '
        f'entry {e(entry.get("id"))}</p>',
        render_source(entry.get("commitment", {}), "The commitment"),
    ]

    observations = entry.get("observations") or []
    if observations:
        for i, observation in enumerate(observations, start=1):
            label = "What the public record shows" if len(observations) == 1 else \
                f"What the public record shows ({i})"
            body.append(render_source(observation, label))
    else:
        body.append(
            "<h3>What the public record shows</h3>"
            '<p class="cite">No public document bearing on this commitment was located. '
            "That absence is the finding.</p>"
        )

    body.append(
        '<div class="assessment">'
        "<h3>Assessment</h3>"
        f'<p><span class="status">{e(STATUS_LABEL.get(status, status))}</span> '
        f'<span class="meta">confidence: {e(assessment.get("confidence"))}</span></p>'
        f"<p>{e(assessment.get('reasoning'))}</p>"
        "<h3>What would change this</h3>"
        f"<p>{e(assessment.get('what_would_change_this'))}</p>"
        "</div>"
    )

    ror = entry.get("right_of_reply") or {}
    if ror.get("response_text"):
        body.append(
            "<h3>Response from the developer</h3>"
            f"<blockquote>{e(ror.get('response_text'))}</blockquote>"
            f'<p class="cite">Received {e(ror.get("response_received_on"))}, '
            "published verbatim.</p>"
        )
    elif ror.get("requested"):
        body.append(
            "<h3>Response from the developer</h3>"
            f'<p class="cite">A draft of this entry was sent to the developer on '
            f'{e(ror.get("requested_on"))}. No response had been received at the time of '
            "publication. Any response will be published here in full.</p>"
        )

    corrections = entry.get("corrections") or []
    if corrections:
        rows = "".join(
            f"<li><strong>{e(c.get('date'))}</strong> — was: {e(c.get('was'))} · "
            f"now: {e(c.get('now'))} · raised by {e(c.get('raised_by'))}</li>"
            for c in corrections
        )
        body.append(f"<h3>Corrections</h3><ul class='cite'>{rows}</ul>")

    coi = entry.get("conflicts_of_interest")
    if coi and coi != "none":
        body.append(f"<h3>Conflict of interest</h3><p>{e(coi)}</p>")

    body.append(
        f'<p class="meta">Last reviewed {e(entry.get("last_reviewed"))} by '
        f'{e(entry.get("reviewer"))}. <a href="index.html">All entries</a></p>'
    )
    return page(f"{entry.get('title')} — Halcyon Threshold", "\n".join(body), built)


def render_index(entries: list[dict], built: str) -> str:
    if entries:
        items = []
        for entry in sorted(entries, key=lambda x: (x.get("developer", ""), x.get("id", ""))):
            status = (entry.get("assessment") or {}).get("status", "unclear")
            items.append(
                f'<li><span class="dev">{e(entry.get("developer"))}</span><br>'
                f'<a href="{e(entry.get("id"))}.html">{e(entry.get("title"))}</a><br>'
                f'<span class="meta">{e(STATUS_LABEL.get(status, status))} · '
                f'reviewed {e(entry.get("last_reviewed"))}</span></li>'
            )
        listing = f"<ul class='entries'>{''.join(items)}</ul>"
    else:
        listing = (
            '<p class="notice">No entries are published yet. The methodology is fixed first, '
            "on purpose: the standard of evidence should not be set by the first awkward "
            "case.</p>"
        )

    body = [
        "<h2>What this is</h2>",
        "<p>Frontier AI developers make public commitments about how they will test, audit "
        "and disclose. Those commitments are spread across policies, frameworks and blog "
        "posts that get revised without notice. This project keeps the record: the "
        "commitment, quoted and archived; the publicly verifiable conduct, quoted and "
        "archived; and a clearly separated assessment that states what evidence would change "
        "it.</p>",
        "<p>Every entry is checkable by following its links. That is the only authority this "
        "project claims.</p>",
        "<h2>Entries</h2>",
        listing,
    ]
    return page("Halcyon Threshold", "\n".join(body), built)


def main() -> int:
    parser = argparse.ArgumentParser(description="Build the static site.")
    parser.add_argument("--out", default="site", help="output directory (default: site)")
    parser.add_argument("--include-drafts", action="store_true",
                       help="render entries that have not completed right of reply")
    args = parser.parse_args()

    out_dir = (ROOT / args.out).resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    built = dt.date.today().isoformat()

    rendered: list[dict] = []
    skipped: list[str] = []

    for path in sorted(ENTRY_DIR.glob("*.json")):
        try:
            entry = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            print(f"error: {path.name}: invalid JSON: {exc}", file=sys.stderr)
            return 1

        if entry.get("placeholder") is True:
            skipped.append(f"{path.name} (placeholder)")
            continue

        status = (entry.get("assessment") or {}).get("status")
        requested = (entry.get("right_of_reply") or {}).get("requested") is True
        if status in ADVERSE_STATUSES and not requested and not args.include_drafts:
            skipped.append(f"{path.name} (right of reply not requested)")
            continue

        (out_dir / f"{entry['id']}.html").write_text(
            render_entry(entry, built), encoding="utf-8")
        rendered.append(entry)

    (out_dir / "index.html").write_text(render_index(rendered, built), encoding="utf-8")

    for name in skipped:
        print(f"skipped {name}")
    print(f"rendered {len(rendered)} entr{'y' if len(rendered) == 1 else 'ies'} to {out_dir}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
